def skill():
    dv = 2*Rational(1, 10)*4 + (-Rational(1, 5))*0
    return 10*(Rational(3, 2) + dv)

def standard():
    a, b, c = symbols('a b c')
    sol = solve([Eq(2*a + 2*b + c, 1), Eq(16*a + 10*b + 4*c - 4, Rational(3, 2))], [b, c], dict=True)[0]
    a0 = Rational(1, 8)
    vals = {a: a0}
    pb = sol[b].subs(vals)
    pc = sol[c].subs(vals)
    py = [a0 + Rational(1, 10), pb, pc - Rational(1, 5), pb, a0 + Rational(1, 10)]
    assert sum(py) == 1
    m = sum(p*x for p, x in zip(py, range(5)))
    return 10*sum(p*(x - m)**2 for p, x in zip(py, range(5)))

def unique():
    # a를 바꿔도 값이 변하지 않음을 확인
    out = set()
    for a0 in (Rational(1, 16), Rational(1, 10), Rational(1, 8)):
        b0 = None
        # 2a+2b+c=1, 16a+10b+4c=11/2 → c=1-2a-2b, 8a+2b=3/2
        b0 = (Rational(3, 2) - 8*a0) / 2
        c0 = 1 - 2*a0 - 2*b0
        py = [a0 + Rational(1, 10), b0, c0 - Rational(1, 5), b0, a0 + Rational(1, 10)]
        m = sum(p*x for p, x in zip(py, range(5)))
        out.add(10*sum(p*(x - m)**2 for p, x in zip(py, range(5))))
    return sorted(out)
